    function _run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcher, uint256 _overhead, uint256 _scalar) internal {
        uint64 n0;
        try c.number() returns (uint64 __r) { n0 = __r; } catch { return; }
        uint256 b0;
        try c.basefee() returns (uint256 __r) { b0 = __r; } catch { return; }
        uint64 s0;
        try c.sequenceNumber() returns (uint64 __r) { s0 = __r; } catch { return; }
